 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0 for _ in range(w)] for _ in range(h)]
    frames = []
    for color in set(x for row in grid for x in row if x):
        pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        r0, r1 = min(r for r, _ in pts), max(r for r, _ in pts)
        c0, c1 = min(c for _, c in pts), max(c for _, c in pts)
        if r1-r0 < 3 or c1-c0 < 3:
            continue
        perimeter = ([(r0,c) for c in range(c0,c1+1)] +
                     [(r1,c) for c in range(c0,c1+1)] +
                     [(r,c0) for r in range(r0,r1+1)] +
                     [(r,c1) for r in range(r0,r1+1)])
        if all(grid[r][c] == color for r,c in perimeter):
            frames.append((r0,r1,c0,c1,color))
            for r,c in perimeter:
                out[r][c] = color
    counts = Counter(grid[r][c] for r in range(h) for c in range(w)
                     if grid[r][c] and out[r][c] == 0)
    used = set()
    for r0,r1,c0,c1,frame_color in frames:
        cells = [(r,c) for r in range(r0+1,r1) for c in range(c0+1,c1)
                 if (r-r0-1 + c-c0-1) % 2 == 0]
        n = len(cells)
        fill = next((col for col, count in counts.items()
                     if col != frame_color and count == n and col not in used), None)
        if fill is None:
            # A checker pattern can have one more cell on the opposite phase.
            fill = next((col for col, count in counts.items()
                         if col != frame_color and count == n+1 and col not in used), None)
            if fill is not None:
                cells = [(r,c) for r in range(r0+1,r1) for c in range(c0+1,c1)
                         if (r-r0-1 + c-c0-1) % 2 == 1]
        if fill is not None:
            used.add(fill)
            for r,c in cells:
                out[r][c] = fill
    return out

